mapper.delete:
DELETE
FROM question_favorite
WHERE user_id = #{userId}
  AND question_id = #{questionId}

mapper.select:
SELECT qf.id, qf.question_id AS questionId, q.title AS questionTitle, q.difficulty AS questionDifficulty, qf.create_time AS createTime FROM question_favorite qf INNER JOIN question q ON q.id = qf.question_id WHERE qf.user_id = #{userId} AND q.is_delete = 0 AND (q.is_member_only = 0 OR #{canViewMemberOnly} = 1)
AND qf.id < #{cursor}
ORDER BY qf.id DESC LIMIT #{limit}
